  "/ja/koi/": "\u003c!doctype html\u003e\n\u003chtml lang=\"ja\"\u003e\n  \u003chead\u003e\n    \u003cmeta charset=\"utf-8\"\u003e\n    \u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1\"\u003e\n    \u003cmeta name=\"description\" content=\"古い一般的な鯉のページは、飼育、品種、健康、池の計画、歴史、購入ガイドなど、より明確なトピックパスに折りたたまれています。\"\u003e\n    \u003clink rel=\"canonical\" href=\"https://mykoigarden.com/ja/koi/\"\u003e\n    \u003clink rel=\"alternate\" hreflang=\"en\" href=\"https://mykoigarden.com/koi/\"\u003e\n    \u003clink rel=\"alternate\" hreflang=\"zh\" href=\"https://mykoigarden.com/zh/koi/\"\u003e\n    \u003clink rel=\"alternate\" hreflang=\"es\" href=\"https://mykoigarden.com/es/koi/\"\u003e\n    \u003clink rel=\"alternate\" hreflang=\"ja\" href=\"https://mykoigarden.com/ja/koi/\"\u003e\n    \u003clink rel=\"alternate\" hreflang=\"x-default\" href=\"https://mykoigarden.com/koi/\"\u003e\n    \u003ctitle\u003e鯉ガイドのトピックがセクションごとに整理されました。 | My Koi Garden\u003c/title\u003e\n    \u003clink rel=\"stylesheet\" href=\"/styles.css\"\u003e\n  \u003c/head\u003e\n  \u003cbody class=\"subpage\"\u003e\n    \u003cheader class=\"site-header\" aria-label=\"Primary\"\u003e\n      \u003ca class=\"brand\" href=\"/ja/\" aria-label=\"My Koi Garden\"\u003e\u003cimg class=\"brand-wordmark\" src=\"/assets/logo-wordmark-transparent.png\" alt=\"My Koi Garden\"\u003e\u003c/a\u003e\n      \u003cnav class=\"nav\" aria-label=\"Site navigation\"\u003e\n        \u003ca href=\"/ja/koi-care/\"\u003e飼育\u003c/a\u003e\u003ca href=\"/ja/koi-history.html\"\u003e歴史\u003c/a\u003e\u003ca href=\"/ja/koi-health/\"\u003e健康\u003c/a\u003e\u003ca href=\"/ja/koi-varieties/\"\u003e品種\u003c/a\u003e\n        \u003ca href=\"/ja/choose-koi/\"\u003e選び方\u003c/a\u003e\u003ca href=\"/ja/pond-guide/\"\u003e池づくり\u003c/a\u003e\u003ca href=\"/ja/koi-qa.html\"\u003eQ\u0026A\u003c/a\u003e\u003ca href=\"/ja/local-koi-for-sale.html\"\u003eローカル販売\u003c/a\u003e\u003ca href=\"/ja/journal/\"\u003e記録\u003c/a\u003e\n        \u003ca href=\"/\"\u003eEN\u003c/a\u003e\u003ca href=\"/zh/\" lang=\"zh\"\u003e中文\u003c/a\u003e\u003ca href=\"/es/\" lang=\"es\"\u003eES\u003c/a\u003e\u003ca href=\"/ja/\" lang=\"ja\"\u003e日本語\u003c/a\u003e\n      \u003c/nav\u003e\n    \u003c/header\u003e\n    \u003cmain\u003e\r\n      \u003csection class=\"page-hero\"\u003e\u003cdiv class=\"page-hero-inner\"\u003e\r\n        \u003cp class=\"section-kicker\"\u003e日本語\u003c/p\u003e\r\n        \u003ch1\u003e鯉ガイドのトピックがセクションごとに整理されました。\u003c/h1\u003e\r\n        \u003cp\u003e古い一般的な鯉のページは、飼育、品種、健康、池の計画、歴史、購入ガイドなど、より明確なトピックパスに折りたたまれています。\u003c/p\u003e\r\n      \u003c/div\u003e\u003c/section\u003e\r\n      \u003csection class=\"article-layout\"\u003e\u003carticle class=\"article\"\u003e\r\n          \u003cp\u003eガイドを更新しました\u003c/p\u003e\r\n          \u003cp\u003e水質、餌付け、飼育、観察、季節ごとの習慣。\u003c/p\u003e\r\n          \u003cp\u003e琥珀、三毛、昭和、黄金、うつり、ベッコウ、アサギ、タンチョウ、ナガヒレなど。\u003c/p\u003e\r\n          \u003cp\u003e病気の予防、症状、治療用品、検疫、水の検査。\u003c/p\u003e\r\n          \u003cp\u003e池の種類、ろ過、建設資材、水生植物、メンテナンスアクセス。\u003c/p\u003e\r\n          \u003cp\u003e中国の鯉文化、新潟セレクション、錦鯉の発展、そして世界のホビー文化。\u003c/p\u003e\r\n          \u003cp\u003e行動、体型、肌質、柄のバランス、販売者への質問。\u003c/p\u003e\r\n        \u003c/article\u003e\r\n        \u003caside class=\"article-aside\"\u003e\r\n          \u003cp class=\"tag\"\u003e日本語\u003c/p\u003e\u003ch2\u003eMy Koi Garden\u003c/h2\u003e\r\n          \u003ca href=\"/ja/koi-care/\"\u003e飼育\u003c/a\u003e\r\n          \u003ca href=\"/ja/koi-varieties/\"\u003e品種\u003c/a\u003e\r\n          \u003ca href=\"/ja/pond-guide/\"\u003e池づくり\u003c/a\u003e\r\n          \u003ca href=\"/ja/koi-health/\"\u003e健康\u003c/a\u003e\r\n        \u003c/aside\u003e\u003c/section\u003e\u003c/main\u003e\r\n\n    \u003cfooter class=\"site-footer\"\u003e\u003cp\u003e© 2026 My Koi Garden. 出典と画像クレジット. \u003ca href=\"/ja/sources.html\"\u003e出典\u003c/a\u003e.\u003c/p\u003e\u003c/footer\u003e\n  \u003c/body\u003e\n\u003c/html\u003e\r\n",
